                       "---\n\n"
                       "## 第一章 线性数据结构\n\n"
                       "### 1.1 数组\n"
                       "- **定义**：一组相同类型元素的有序集合，内存连续分配\n"
                       "- **特点**：\n"
                       "  - 随机访问：O(1)\n"
                       "  - 插入删除：O(n)\n"
                       "  - 内存连续\n"
                       "- **分类**：\n"
                       "  - 静态数组：大小固定\n"
                       "  - 动态数组：大小可变（如Python list）\n\n"
                       "### 1.2 链表\n"
                       "- **定义**：由节点组成的线性结构，每个节点包含数据和指针\n"
                       "- **特点**：\n"
                       "  - 随机访问：O(n)\n"
                       "  - 插入删除：O(1)（已知位置）\n"
                       "  - 内存非连续\n"
                       "- **分类**：\n"
                       "  - 单链表：每个节点只有一个指针\n"
                       "  - 双链表：每个节点有两个指针（前驱和后继）\n"
                       "  - 循环链表：最后一个节点指向头节点\n\n"
                       "### 1.3 栈\n"
                       "- **定义**：后进先出(LIFO)的线性结构\n"
