                       "## 第二章 树形数据结构\n\n"
                       "### 2.1 树的基本概念\n"
                       "- **节点**：包含数据和子节点指针\n"
                       "- **根节点**：树的最顶层节点\n"
                       "- **叶子节点**：没有子节点的节点\n"
                       "- **深度**：从根到该节点的路径长度\n"
                       "- **高度**：从该节点到最远叶子节点的路径长度\n\n"
                       "### 2.2 二叉树\n"
                       "- **定义**：每个节点最多有两个子节点\n"
                       "- **性质**：\n"
                       "  - 第k层最多有2ᵏ⁻¹个节点\n"
                       "  - n层二叉树最多有2ⁿ-1个节点\n"
                       "- **遍历方式**：\n"
                       "  - 前序遍历：根→左→右\n"
                       "  - 中序遍历：左→根→右\n"
                       "  - 后序遍历：左→右→根\n"
                       "  - 层序遍历：按层访问\n\n"
                       "### 2.3 二叉搜索树(BST)\n"
                       "- **定义**：左子树所有节点<根<右子树所有节点\n"
                       "- **操作**：\n"
                       "  - 查找：O(log n)（平衡时）\n"
                       "  - 插入：O(log n)\n"
                       "  - 删除：O(log n)\n"
                       "- **缺点**：可能退化为链表\n\n"
                       "### 2.4 平衡树\n"
                       "- **AVL树**：任意节点左右子树高度差≤1\n"
                       "- **红黑树**：通过颜色约束保证近似平衡\n"
                       "- **B树/B+树**：多路平衡搜索树，用于数据库索引\n\n"
                       "### 2.5 堆\n"
                       "- **定义**：完全二叉树，父节点≥子节点（大顶堆）或父节点≤子节点（小顶堆）\n"
                       "- **操作**：\n"
                       "  - 插入：O(log n)\n"
                       "  - 删除堆顶：O(log n)\n"
                       "- **应用**：\n"
