                       "- **优缺点**：\n"
                       "  - 邻接矩阵：查询O(1)，空间O(n²)\n"
                       "  - 邻接表：查询O(d)，空间O(n+m)\n\n"
                       "### 3.3 图的遍历\n"
                       "- **深度优先搜索(DFS)**：递归访问，回溯\n"
