                       "### 3.4 最短路径算法\n"
                       "- **Dijkstra算法**：单源最短路径，适用于非负权边\n"
                       "- **Floyd算法**：多源最短路径，动态规划\n"
                       "- **Bellman-Ford算法**：处理负权边\n\n"
                       "### 3.5 最小生成树\n"
                       "- **Prim算法**：贪心，从顶点出发\n"
