                       "---\n\n"
                       "## 第一章 时间复杂度\n\n"
                       "### 1.1 基本概念\n"
                       "- **时间复杂度**：算法执行所需时间与输入规模的关系\n"
                       "- **大O表示法**：描述最坏情况下的时间复杂度\n"
                       "- **常见复杂度**：\n"
                       "  - O(1)：常数时间\n"
                       "  - O(log n)：对数时间\n"
                       "  - O(n)：线性时间\n"
                       "  - O(n log n)：线性对数时间\n"
                       "  - O(n²)：平方时间\n"
                       "  - O(n³)：立方时间\n"
                       "  - O(2ⁿ)：指数时间\n\n"
                       "### 1.2 分析方法\n"
                       "- **只看最高阶项**：忽略低阶项\n"
                       "- **忽略常数系数**：O(2n) = O(n)\n"
                       "- **加法法则**：取最大值\n"
                       "- **乘法法则**：嵌套循环相乘\n\n"
                       "### 1.3 常见算法复杂度\n"
                       "- **数组遍历**：O(n)\n"
                       "- **二分查找**：O(log n)\n"
                       "- **冒泡排序**：O(n²)\n"
                       "- **快速排序**：O(n log n)（平均）\n"
                       "- **归并排序**：O(n log n)\n"
                       "- **矩阵乘法**：O(n³)\n\n"
                       "---\n\n"
                       "## 第二章 空间复杂度\n\n"
                       "### 2.1 基本概念\n"
                       "- **空间复杂度**：算法执行所需内存与输入规模的关系\n"
                       "- **分类**：\n"
                       "  - O(1)：常数空间\n"
                       "  - O(n)：线性空间\n"
                       "  - O(n²)：平方空间\n\n"
                       "### 2.2 分析方法\n"
                       "- **额外空间**：算法执行过程中临时占用的空间\n"
                       "- **递归栈空间**：递归调用的栈空间\n\n"
