                       "## 第三章 渐进符号\n\n"
                       "### 3.1 大O符号\n"
                       "- **定义**：f(n) = O(g(n))，存在c>0, n₀>0，当n≥n₀时，f(n) ≤ c·g(n)\n"
                       "- **含义**：g(n)是f(n)的上界\n\n"
                       "### 3.2 大Ω符号\n"
                       "- **定义**：f(n) = Ω(g(n))，存在c>0, n₀>0，当n≥n₀时，f(n) ≥ c·g(n)\n"
                       "- **含义**：g(n)是f(n)的下界\n\n"
                       "### 3.3 大Θ符号\n"
                       "- **定义**：f(n) = Θ(g(n))，当且仅当f(n) = O(g(n))且f(n) = Ω(g(n))\n"
                       "- **含义**：g(n)是f(n)的紧界\n\n"
                       "---\n\n"
                       "## 学习要点总结\n\n"
