                       "概率论研究随机现象的规律，统计学研究数据的收集、分析和推断。\n\n"
                       "---\n\n"
                       "## 第一章 概率论基础\n\n"
                       "### 1.1 随机事件\n"
                       "- **随机试验**：可重复、结果不确定\n"
                       "- **样本空间**：所有可能结果的集合\n"
                       "- **随机事件**：样本空间的子集\n"
                       "- **必然事件**：Ω，不可能事件：∅\n\n"
                       "### 1.2 概率公理\n"
                       "- P(A) ≥ 0\n"
                       "- P(Ω) = 1\n"
                       "- 互斥事件可加性：P(A∪B) = P(A)+P(B)\n\n"
                       "### 1.3 条件概率\n"
                       "- **条件概率定义**：P(B|A) = P(A∩B)/P(A)\n"
                       "- **乘法公式**：P(A∩B) = P(A)·P(B|A)\n"
                       "- **全概率公式**：P(B) = ΣP(Aᵢ)·P(B|Aᵢ)\n"
                       "- **贝叶斯公式**：P(Aᵢ|B) = P(Aᵢ)·P(B|Aᵢ)/P(B)\n\n"
                       "---\n\n"
                       "## 第二章 随机变量\n\n"
                       "### 2.1 随机变量的概念\n"
                       "- **随机变量定义**：从样本空间到实数的映射\n"
                       "- **离散型**：取值有限或可数\n"
                       "- **连续型**：取值连续\n\n"
                       "### 2.2 分布函数\n"
                       "- **分布函数定义**：F(x) = P(X≤x)\n"
                       "- **性质**：单调不减、右连续、F(-∞)=0, F(+∞)=1\n\n"
                       "### 2.3 离散型分布\n"
