                       "### 2.4 连续型分布\n"
                       "- **均匀分布**：U(a,b)，区间内概率均匀\n"
                       "- **正态分布**：N(μ,σ²)，钟形曲线\n"
                       "- **指数分布**：Exp(λ)，无记忆性\n"
                       "- **伽马分布**：Γ(α,λ)\n\n"
                       "---\n\n"
                       "## 第三章 数字特征\n\n"
                       "### 3.1 数学期望\n"
                       "- **离散型**：E(X) = Σxᵢ·P(X=xᵢ)\n"
                       "- **连续型**：E(X) = ∫x·f(x)dx\n"
                       "- **期望性质**：E(aX+b) = aE(X)+b, E(X+Y)=E(X)+E(Y)\n\n"
                       "### 3.2 方差\n"
                       "- **方差定义**：Var(X) = E[(X-E(X))²]\n"
                       "- **计算公式**：Var(X) = E(X²) - [E(X)]²\n"
                       "- **方差性质**：Var(aX+b) = a²Var(X)\n\n"
                       "### 3.3 协方差与相关系数\n"
                       "- **协方差**：Cov(X,Y) = E[(X-E(X))(Y-E(Y))]\n"
                       "- **相关系数**：ρ = Cov(X,Y)/(σₓσᵧ)\n"
                       "- **性质**：|ρ|≤1，ρ=0不相关\n\n"
