                       "## 第四章 大数定律与中心极限定理\n\n"
                       "### 4.1 大数定律\n"
                       "- **切比雪夫大数定律**：样本均值依概率收敛于总体均值\n"
                       "- **伯努利大数定律**：频率依概率收敛于概率\n"
