                       "热力学研究热现象和能量转化规律，是物理学的重要分支。\n\n"
                       "---\n\n"
                       "## 第一章 温度与热平衡\n\n"
                       "### 1.1 温度\n"
                       "- **温度定义**：物体冷热程度的量度\n"
                       "- **温度计**：利用热胀冷缩原理\n"
                       "- **温标**：摄氏温标、华氏温标、热力学温标\n\n"
                       "### 1.2 热平衡\n"
                       "- **热平衡**：两物体温度相同时达到平衡\n"
                       "- **热力学第零定律**：若A与B平衡，B与C平衡，则A与C平衡\n\n"
                       "### 1.3 理想气体状态方程\n"
                       "- **公式**：pV = nRT\n"
                       "- **气体常数**：R = 8.31 J/(mol·K)\n"
                       "- **特殊情况**：等温、等容、等压过程\n\n"
                       "---\n\n"
                       "## 第二章 热量与热传递\n\n"
                       "### 2.1 热量\n"
                       "- **热量定义**：热传递过程中能量的变化量\n"
                       "- **比热容**：c = Q/(mΔT)\n"
                       "- **潜热**：Q = L·m\n\n"
                       "### 2.2 热传递方式\n"
                       "- **热传导**：通过分子碰撞传递热量\n"
                       "- **热对流**：通过流体流动传递热量\n"
                       "- **热辐射**：通过电磁波传递热量\n\n"
                       "---\n\n"
                       "## 第三章 热力学定律\n\n"
                       "### 3.1 热力学第一定律\n"
                       "- **内容**：能量守恒\n"
                       "- **公式**：ΔU = Q - W\n"
                       "- **符号约定**：Q为正吸热，W为正对外做功\n\n"
                       "### 3.2 热力学第二定律\n"
                       "- **克劳修斯表述**：热量不能自发从低温传向高温\n"
                       "- **开尔文表述**：不可能从单一热源吸热全部转化为功\n"
                       "- **熵增原理**：孤立系统熵不会减少\n\n"
                       "### 3.3 热力学第三定律\n"
                       "- **内容**：绝对零度不可达到\n"
                       "- **表达式**：lim(T→0) S = 0\n\n"
                       "---\n\n"
                       "## 第四章 熵\n\n"
                       "### 4.1 熵的定义\n"
                       "- **熵的定义**：dS = dQ/T\n"
                       "- **熵的性质**：状态函数，与路径无关\n\n"
                       "### 4.2 熵增原理\n"
                       "- **孤立系统**：ΔS ≥ 0\n"
                       "- **可逆过程**：ΔS = 0\n"
                       "- **不可逆过程**：ΔS > 0\n\n"
                       "### 4.3 自由能\n"
                       "- **亥姆霍兹自由能**：F = U - TS\n"
                       "- **吉布斯自由能**：G = H - TS\n\n"
