                       "- **压强**：分子碰撞器壁产生\n"
                       "- **温度**：分子平均动能的量度\n\n"
                       "---\n\n"
                       "## 学习要点总结\n\n"
                       "1. **温度与热平衡**是热力学的基础\n"
                       "2. **热力学第一定律**是能量守恒在热现象中的应用\n"
                       "3. **热力学第二定律**揭示了自然过程的方向性\n"
