# 评估维度ID到基础分数的映射 — 用于MOCK_EVALUATION的动态生成
_MOCK_EVAL_BASE_SCORES = {
    "knowledge": 75,
    "understanding": 68,
    "application": 62,
    "analysis": 58,
    "creativity": 55,
    "self_learning": 70,
}

_MOCK_EVAL_DIM_NAMES = {
    "knowledge": "知识掌握",
    "understanding": "理解深度",
    "application": "应用能力",
    "analysis": "分析评价",
    "creativity": "创新思维",
    "self_learning": "自主学习力",
}

_MOCK_EVAL_DIM_STRENGTH_THRESHOLD = 62  # 高于此分为优势维度
_MOCK_EVAL_DIM_WEAK_THRESHOLD = 55  # 低于此分为薄弱维度


def _mock_evaluation(user_content):
    """生成动态评估mock数据，匹配 full_evaluate 和前端 displayResult 期望的格式"""
    # 随机构造维度分数（在基线附近抖动）
    scores = {}
    for dim_id, base in _MOCK_EVAL_BASE_SCORES.items():
        score = max(30, min(100, base + random.randint(-8, 10)))
        scores[dim_id] = score

    # 计算加权综合分
    from evaluation_engine import EVAL_DIMENSIONS
    weighted = sum(scores[d["id"]] * d["weight"] for d in EVAL_DIMENSIONS)
    overall = round(weighted)

    # 按分数排序确定优势和薄弱
    sorted_dims = sorted(EVAL_DIMENSIONS, key=lambda d: scores[d["id"]], reverse=True)
    strengths = [
        f"{d['name']}表现较好（{scores[d['id']]}分）——{d['desc']}"
        for d in sorted_dims if scores[d["id"]] >= _MOCK_EVAL_DIM_STRENGTH_THRESHOLD
    ] or ["各维度表现均衡"]
    weaknesses = [
        f"{d['name']}需加强（{scores[d['id']]}分）——目前在该维度的表现还有明显提升空间"
        for d in sorted_dims if scores[d["id"]] < _MOCK_EVAL_DIM_WEAK_THRESHOLD
    ]

    # 调级判定
    min_dim = min(scores.values())
    if overall >= 80 and min_dim >= 65:
        action = "upgrade"
    elif overall >= 50:
        action = "stay"
    elif overall >= 25:
        action = "consolidate"
    else:
        action = "customize"

    # 动态摘要
    weak_names = [d["name"] for d in sorted_dims if scores[d["id"]] < _MOCK_EVAL_DIM_WEAK_THRESHOLD]
    if weak_names:
        weak_part = f"需重点关注{'、'.join(weak_names[:3])}等维度"
    else:
        weak_part = "各维度无明显短板"
    strong_part = f"在{'、'.join(d['name'] for d in sorted_dims[:2])}方面表现突出" if len(strengths) >= 2 else "基础扎实"
    summary = f"综合评分{overall}分。{strong_part}，{weak_part}。"

    # 建议
    recommendations = []
    if weak_names:
        recommendations.append(f"优先巩固：{'、'.join(weak_names[:2])}，建议增加相关练习和案例分析")
    recommendations.append("保持现有学习节奏，定期自测检验学习效果")
    if action == "upgrade":
        recommendations.append("各维度表现达标，可挑战更高层次的项目实战")
    elif action == "consolidate":
        recommendations.append("暂停新内容推进，系统回顾已学知识点")

    suggestions = {
        "upgrade": "可以升级到更高层次，挑战更复杂的内容",
        "stay": "保持当前学习节奏，重点关注短板维度",
        "consolidate": "建议暂停推进新内容，集中巩固已有知识点",
        "customize": "需定制个性化学习方案",
    }

    confidence = round(min(0.8, 0.45 + len(strengths) * 0.05 + (1 if weaknesses else 0) * 0.05), 2)

    return json.dumps({
        "dimension_scores": scores,
        "overall": overall,
        "summary": summary,
        "strengths": strengths,
        "weaknesses": weaknesses,
        "recommendations": recommendations,
        "suggested_action": action,
        "suggested_action_label": suggestions.get(action, "保持当前"),
        "confidence": confidence,
    }, ensure_ascii=False)

