def _mock_tutor_response(user_content):
    """根据用户问题关键词生成差异化的演示辅导回答"""
    import re
    question = ""
    last_student_q = re.search(r'学生最新提问[：:](.+?)$', user_content, re.MULTILINE)
    if last_student_q:
        question = last_student_q.group(1).strip()
    if not question or len(question) < 2:
        return (
            '这是一个值得深入的问题。\n\n'
            '学习任何新知识，关键三步走：第一，建立基本概念框架；'
            '第二，在框架中找到你问的具体问题的位置；'
            '第三，通过举例和联系已有知识来加深理解。\n\n'
            '> 你能先说说你目前了解到了什么程度吗？'
        )
    q = question[:60]
    q_lower = q.lower()
    if any(w in q_lower for w in ['什么是', '概念', '定义', '解释', '含义', '意思']):
        return (
            f'关于「{q}」这个概念，我们从定义出发来理一理。\n\n'
            f'第一步，先明确它的核心定义：这个概念描述的是什么对象或现象？它的本质特征是什么？\n'
            '第二步，看看它和相近概念的区别在哪里。如果你能说出两三个关键区别，说明你真的理解了。\n'
            f'第三步，能否举一个你熟悉的例子来对应这个概念？例子越贴近你的日常经验越好。\n\n'
            f'> 你可以先说说你对「{q}」当前的理解，然后我们一起往下推。'
        )
    if any(w in q_lower for w in ['怎么', '如何', '方法', '步骤', '实现', '做']):
        return (
            f'关于「{q}」这个操作类问题，我们可以按流程拆开来看。\n\n'
            '第一步，确保前置条件满足——做这件事之前需要掌握哪些基础知识？\n'
            '第二步，按规范的流程一步一步走。不要跳过任何中间步骤，每一步做完检查结果。\n'
            '第三步，如果遇到报错或异常结果，分析错误信息——它通常告诉了你问题出在哪一步。\n\n'
            '> 你做到哪一步了？把卡住的地方具体说说，我帮你定位。'
        )
    if any(w in q_lower for w in ['区别', '对比', 'vs', '不同', '差异']):
        return (
            f'要对比「{q}」之间的区别，建议你从三个维度来看。\n\n'
            '第一，各自的核心定义是什么？定义往往已经决定了适用的场景。\n'
            '第二，适用的场景有何不同——什么情况下用A而不用B？\n'
            '第三，各自的优缺点——没有完美的方案，知道取舍就好。\n\n'
            f'> 我建议你画一个对比表格，把「{q}」的行列填好，一目了然。你更关注哪个维度的差异？'
        )
    if any(w in q_lower for w in ['代码', '编程', '实现', '报错', 'error', 'bug', '调试']):
        return (
            f'关于「{q}」的编程问题，我们先确认一下边界。\n\n'
            '第一，你在什么环境下遇到这个问题？语言、框架、版本。\n'
            '第二，错误发生时你在做什么操作——完整复现路径比报错信息本身更重要。\n'
            '第三，把问题拆小：先保证核心逻辑正确，再去处理边界条件和异常。\n\n'
            f'> 把你遇到的报错信息贴出来，或者说说你期望的行为和实际行为之间的差距。'
        )
    if any(w in q_lower for w in ['推荐', '学习', '资源', '教程', '书', '课程']):
        return (
            f'关于「{q}」的学习资源推荐，我建议分阶段来选。\n\n'
            '入门阶段：找一本体系清晰的教材或一门优质的公开课，跟着走完一遍。\n'
            '进阶阶段：读官方文档和经典案例，动手做项目来巩固理解。\n'
            '深入阶段：看论文、源码、参与社区讨论。\n\n'
            f'> 你目前处于哪个阶段？我可以针对性地推荐适合你当前水平的学习材料。'
        )
    if any(w in q_lower for w in ['考试', '复习', '重点', '考点', '总结']):
        return (
            f'关于「{q}」的复习备考，建议你按三轮来安排。\n\n'
            '第一轮，通读教材和笔记，建立完整的知识框架图。\n'
            '第二轮，重点突破薄弱环节，做针对性练习。\n'
            '第三轮，模拟考试环境成套刷题，查漏补缺。\n\n'
            f'> 你可以先说说这门课的考核形式，以及你觉得自己哪些章节最薄弱。'
        )
    return (
        f'关于「{q}」，这是一个值得深入的问题。\n\n'
        '学习任何新知识，关键三步走：第一，建立基本概念框架；'
        '第二，在框架中找到你问的具体问题的位置；'
        '第三，通过举例和联系已有知识来加深理解。\n\n'
        f'> 你能先说说你对「{q}」目前了解到了什么程度吗？'
    )



