def _get_mock_resource(subject, resource_type, filter_type=None, level=None, profile=None, topic=None):
    """从mock数据池中获取指定学科和类型的资源
    
    Args:
        subject: 学科key
        resource_type: 资源类型 (document/mindmap/quiz/case)
        filter_type: 题目类型过滤 (choice/fill/short_answer/code)
        level: 学生等级 (1-4), 用于过滤匹配等级的mock资源
        topic: 主题关键词, 用于主题匹配过滤(优先返回匹配的条目)
        profile: 学生画像dict (含cognitive_style, weak_points等), 用于偏好排序
    Returns:
        dict: 选中的资源条目
    """
    subject_data = MOCK_RESOURCES.get(subject, MOCK_RESOURCES.get("computer_science"))
    default_subject = MOCK_RESOURCES["computer_science"]
    
    # 资源类型到MOCK_RESOURCES字段键的映射
    type_key_map = {"document": "docs", "mindmap": "mindmaps", "quiz": "quizzes", "case": "cases"}
    key = type_key_map.get(resource_type, "docs")
    
    # 获取该类型的资源列表 + fallback
    items = subject_data.get(key, None)
    if not items:
        items = subject_data.get("quiz", None)  # quiz回头兼容
    if not items:
        items = default_subject.get(key, default_subject["docs"])
    
    # 对于quiz类型，先根据题目类型过滤
    if resource_type == "quiz" and filter_type and items:
        filtered = [item for item in items if item.get("type") == filter_type]
        if filtered:
            items = filtered
    
    if not items:
        return default_subject["docs"][0]
    
    # ===== 主题匹配: 优先返回与topic相关的案例 =====
    # 如果topic提供了且资源类型是case, 检测案例标题/描述/关键词是否匹配
    if topic and resource_type == "case" and items:
        topic_lower = topic.lower().strip()
        topic_candidates = []  # [(match_priority, item), ...]  0=最高
        for item in items:
            title = item.get("title", "").lower()
            desc = item.get("description", "").lower()
            kp = item.get("knowledge_point", "").lower()
            item_topics = item.get("topics", [])
            item_topics_lower = [t.lower() for t in item_topics]
            
            priority = None
            # 优先级0: 标题包含topic(最精确)
            if topic_lower in title:
                priority = 0
            # 优先级1: topics数组包含topic
            elif any(topic_lower in t for t in item_topics_lower):
                priority = 1
            # 优先级2: 描述包含topic
            elif topic_lower in desc:
                priority = 2
            # 优先级3: 知识点包含topic(最宽松)
            elif topic_lower in kp:
                priority = 3
            
            if priority is not None:
                topic_candidates.append((priority, item))
        
        if topic_candidates:
            # 按优先级排序, 同优先级随机
            topic_candidates.sort(key=lambda x: (x[0], random.random()))
            best_priority = topic_candidates[0][0]
            best = [x[1] for x in topic_candidates if x[0] == best_priority]
            items = best
        else:
            # 二级匹配: 全串匹配 + 空格分词匹配
            # 对于中文, 使用全串匹配(如'网络编程'匹配含'网络编程'的项)
            # 对于英文短语或中英混合, 按空格分词匹配
            topic_words = set()
            topic_words.add(topic_lower)  # 全串优先
            # 空格分词: 'python 装饰器' -> ['python', '装饰器']
            for w in topic_lower.split():
                if len(w) >= 2:
                    topic_words.add(w)
            topic_words = list(topic_words)
            
            word_candidates = []
            for item in items:
                title = item.get("title", "").lower()
                desc = item.get("description", "").lower()
                kp = item.get("knowledge_point", "").lower()
                item_topics = item.get("topics", [])
                item_topics_lower = [t.lower() for t in item_topics]
                match_text = title + " " + desc + " " + kp + " " + " ".join(item_topics_lower)
                if any(w in match_text for w in topic_words):
                    word_candidates.append(item)
            if word_candidates:
                items = word_candidates
            else:
                # 无匹配: 返回None让Agent用主题感知模板
                return None
    
    # ===== 画像感知排序: 按level + cognitive_style匹配度排序 =====
    if level is not None or (profile and profile.get("has_profile")):
        # 获取该资源类型在索引中的字段键
        idx_key = RESOURCE_COUNTS.get(resource_type, key)
        subject_index = MOCK_PROFILE_INDEX.get(subject, {})
        type_index = subject_index.get(idx_key, {})
        
        cognitive_style = "综合型"
        if profile and profile.get("has_profile"):
            cognitive_style = profile.get("cognitive_style", "综合型")
        
        scored = []
        for idx, item in enumerate(items):
            meta = type_index.get(idx, {})
            item_level = meta.get("level", 2)
            item_tags = meta.get("tags", [])
            score = 0
            
            # 等级匹配: 距离越小分越高
            if level is not None:
                level_diff = abs(item_level - level)
                level_score = max(0, 10 - level_diff * 2)  # 0-10分
                score += level_score * 3  # 等级权重3
            
            # 认知风格匹配: 有匹配标签加分
            if cognitive_style != "综合型" and cognitive_style in item_tags:
                score += 15  # 风格匹配权重15
            elif not item_tags or cognitive_style == "综合型":
                score += 5   # 综合型或未标注则给基础分
            
            # 薄弱点匹配: 如果资源tag包含实践驱动型且背景是应用薄弱,加分
            if profile and profile.get("has_profile"):
                weak_points = profile.get("weak_points", [])
                if "application" in weak_points and "实践驱动型" in item_tags:
                    score += 10
                if "understanding" in weak_points and "系统理论型" in item_tags:
                    score += 10
                if "memory" in weak_points and "视听学习型" in item_tags:
                    score += 10
            
            scored.append((score, idx, item))
        
        # 按分数从高到低排序，同分随机
        scored.sort(key=lambda x: (-x[0], random.random()))
        best_score = scored[0][0] if scored else 0
        
        # 只从最高分的一组中随机选(增加多样性)
        best_items = [x for x in scored if x[0] == best_score]
        return random.choice(best_items)[2]
    
    # 无画像时: 原随机逻辑
    return random.choice(items) if items else default_subject["docs"][0]


def _match_intent(system_prompt, user_content):
    """根据prompt关键词识别请求意图"""
    combined = (system_prompt + " " + user_content).lower()
    sys_lower = system_prompt.lower()

    # 优先匹配系统提示词中明确的意图声明（最可靠）
    if "教育评估专家" in sys_lower or ("评估" in sys_lower and "dimension_scores" in combined):
        return "evaluation"

    if any(w in combined for w in ["画像", "profile", "画像构建", "profilebuilder", "学习画像"]):
        return "profile"
    if any(w in combined for w in ["陷阱题", "克星题", "trap", "认知弱点"]):
        return "trap_exam"
    if any(w in combined for w in ["quiz", "题目", "试题", "习题", "question", "选择题"]):
        return "quiz"
    if any(w in combined for w in ["路径", "path", "学习计划", "plan"]):
        return "path"
    if any(w in combined for w in ["mindmap", "导图", "思维导图", "mermaid"]):
        return "mindmap"
    if any(w in combined for w in ["辅导", "tutor", "苏格拉底"]):
        return "tutor"
    if any(w in combined for w in ["case", "案例", "项目案例", "案例分析", "项目实战"]):
        return "case"
    if any(w in combined for w in ["文档", "document", "doc", "讲解", "课程"]):
        return "document"

    return "document"


