def get_mock_response(system_prompt, user_content):
    """根据意图返回对应的mock数据

    Args:
        system_prompt: LLM系统提示词
        user_content: 用户输入内容
    Returns:
        str or None: mock响应文本，未匹配意图返回None
    """
    intent = _match_intent(system_prompt, user_content)

    # 从user_content中提取学科（优先匹配中文名称）
    subject = "computer_science"
    level = None  # 提取学生等级
    profile_tags = {}  # 提取画像信息
    
    # 提取学科字段的值（只从"学科："后面提取）
    subject_value = ""
    if "学科：" in user_content:
        parts = user_content.split("学科：", 1)[1]
        if "\n" in parts:
            subject_value = parts.split("\n")[0].strip()
        else:
            subject_value = parts.strip()
    
    # 1. 先匹配中文学科名称（只在学科字段值中匹配）
    if subject_value:
        for chinese_name, english_key in CHINESE_SUBJECT_MAP.items():
            if chinese_name in subject_value:
                subject = english_key
                break
    
    # 2. 再匹配英文key（兼容旧逻辑）
    if subject == "computer_science":
        for subj in MOCK_RESOURCES:
            if subj in subject_value.lower().replace(" ", "_"):
                subject = subj
                break
    
    # 3. 提取学生等级（支持数字和中文等级名）
    import re as _re
    level_num = _re.search(r'学生水平[：:]\s*(\d+)', user_content)
    level_cn = _re.search(r'学生水平[：:]\s*(基础入门|中等进阶|高级深化|大神专题)', user_content)
    if level_num:
        level = int(level_num.group(1))
    elif level_cn:
        level_name_map = {'基础入门': 1, '中等进阶': 2, '高级深化': 3, '大神专题': 4}
        level = level_name_map[level_cn.group(1)]
    
    # 4. 提取认知风格（格式: "风格说明：XXX"）
    style_match = _re.search(r'风格说明[：:]\s*([^\n]+)', user_content)
    
    # 5. 提取薄弱维度（格式: "薄弱点：[xxx, yyy]" 或 "薄弱点：xxx, yyy"）
    weak_match = _re.search(r'薄弱点[：:]\s*(.*?)(?:\n|$)', user_content)
    weak_points = []
    if weak_match:
        wp_text = weak_match.group(1).strip()
        # 去掉方括号
        wp_text = wp_text.strip('[]').strip("'\"")
        weak_points = [w.strip() for w in wp_text.split(',') if w.strip()]
    
    # 构建简化profile dict用于选材
    if style_match or weak_points:
        profile_tags['has_profile'] = True
        profile_tags['cognitive_style'] = style_match.group(1).strip() if style_match else "综合型"
        profile_tags['weak_points'] = weak_points

    if intent == "evaluation":
        return _mock_evaluation(user_content)

    if intent == "profile":
        from agents.generator_agents import ProfileBuilderAgent
        p = ProfileBuilderAgent()
        conversation = []
        lines = user_content.split('\n')
        current_stage_idx = 0
        stages = p.STAGES
        
        for i in range(0, len(lines), 2):
            if i + 1 < len(lines):
                q_line = lines[i].strip()
                a_line = lines[i + 1].strip()
                if q_line.startswith('Q: ') and a_line.startswith('A: '):
                    answer = a_line[3:].strip()
                    stage = stages[current_stage_idx] if current_stage_idx < len(stages) else f'stage_{current_stage_idx}'
                    conversation.append({'stage': stage, 'answer': answer})
                    current_stage_idx += 1
        
        profile = p._rules_analyze(conversation)
        return json.dumps(profile, ensure_ascii=False)

    if intent == "trap_exam":
        return json.dumps(random.choice(MOCK_TRAP_EXAMS), ensure_ascii=False)

    if intent == "path":
        return json.dumps(MOCK_PATH, ensure_ascii=False)

    if intent == "tutor":
        return _mock_tutor_response(user_content)

    if intent == "mindmap":
        r = _get_mock_resource(subject, "mindmap", level=level, profile=profile_tags)
        return r["code"]

    if intent == "quiz":
        filter_type = None
        if "选择题" in user_content:
            filter_type = "choice"
        elif "填空题" in user_content:
            filter_type = "fill"
        elif "简答题" in user_content:
            filter_type = "short_answer"
        elif "编程题" in user_content:
            filter_type = "code"
        r = _get_mock_resource(subject, "quiz", filter_type, level=level, profile=profile_tags)
        return json.dumps(r, ensure_ascii=False)

    if intent == "case":
        # 提取主题用于topic感知匹配
        topic = None
        topic_match = _re.search(r'与([^，。；\n]+)相关', user_content)
        if topic_match:
            topic = topic_match.group(1).strip()
        if not topic:
            topic_match = _re.search(r'关于([^，。；\n]+)的', user_content)
            if topic_match:
                topic = topic_match.group(1).strip()
        if not topic:
            topic_match = _re.search(r'主题[：:][\s]*([^\n]+)', user_content)
            if topic_match:
                topic = topic_match.group(1).strip()
        r = _get_mock_resource(subject, "case", level=level, profile=profile_tags, topic=topic)
        if r is None:
            return None
        return json.dumps(r, ensure_ascii=False)

    if intent == "document":
        r = _get_mock_resource(subject, "document", level=level, profile=profile_tags)
        return r["content"]

    return None
